// Generates the design-canvas artboards (design/canvas/*.dc.html) from compact view specs.
// Every board is composed from the product's own stylesheets (tokens.css, app.css,
// mesh2.css, uploaded to the canvas) and the shared hero illustrations, so the design
// reference and the app speak one design system. Sample devices and values are fictional.
//   node scripts/design-boards.mjs            write the boards and canvas.json layout
//   node scripts/design-boards.mjs --check    exit 1 when the checked-in boards differ
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import { docFiles } from './lib/doc-articles.mjs';
import { ADDITION_BOARDS, defineAdditions } from './lib/board-additions.mjs';

const require = createRequire(import.meta.url);
const { ART } = require('../src/shared/hero-art.js');
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dir = path.join(root, 'design', 'canvas');
const assetFiles = JSON.parse(fs.readFileSync(path.join(dir, 'assets.json'), 'utf8')).files;
const assets = Object.keys(assetFiles).filter((u) => assetFiles[u].endsWith('.css'));
/** The canvas URL of an uploaded snapshot file such as assets/shot-dark.webp. */
const assetUrl = (file) => { const u = Object.keys(assetFiles).find((k) => assetFiles[k] === file); if (!u) throw new Error(`${file} is not uploaded to the canvas (design/canvas/assets.json)`); return u; };
// The second canvas ("Everything added") lives in design/additions with its own uploads.
const dir2 = path.join(root, 'design', 'additions');
const assetFiles2 = fs.existsSync(path.join(dir2, 'assets.json')) ? JSON.parse(fs.readFileSync(path.join(dir2, 'assets.json'), 'utf8')).files : {};
const assets2 = Object.keys(assetFiles2).filter((u) => assetFiles2[u].endsWith('.css'));
const assetUrl2 = (file) => Object.keys(assetFiles2).find((k) => assetFiles2[k] === file) || '';
const ARTICLES = docFiles(root).length; // the same count the app and the website show

// ---------- tiny markup helpers (all output is static, escaped by hand) ----------
const ms = (n, cls = '') => `<span class="msr${cls}" aria-hidden="true">${n}</span>`;
const btn = (label, icon, cls = '') => `<button type="button" class="btn${cls ? ' ' + cls : ''}">${icon ? ms(icon) : ''}${label}</button>`;
const ibtn = (icon, label) => `<button type="button" class="icon-btn" aria-label="${label}">${ms(icon)}</button>`;
const chip = (label, pressed) => pressed === undefined ? `<span class="chip">${label}</span>` : `<button type="button" class="chip choice" aria-pressed="${pressed}">${label}</button>`;
const badge = (t, tone = 'info') => `<span class="badge ${tone}">${t}</span>`;
const sw = (label, desc, on) => `<div class="switch-row"><div class="txt"><b>${label}</b>${desc ? `<span class="small muted">${desc}</span>` : ''}</div><button type="button" class="switch" role="switch" aria-checked="${on}" aria-label="${label}"></button></div>`;
const seg = (opts, sel, label = 'Choice', wrapped = false) => `<div class="seg${wrapped ? ' wrapped' : ''}" role="radiogroup" aria-label="${label}">${opts.map((o) => `<button type="button" role="radio" aria-checked="${o === sel}">${o}</button>`).join('')}</div>`;
const field = (ph, val = '', label = ph) => `<input class="input" aria-label="${label}" placeholder="${ph}" value="${val}" style="width: 100%">`;
const search = (ph) => `<div class="input-wrap" style="flex: 1; min-width: 220px">${ms('search')}<input aria-label="${ph}" placeholder="${ph}"><button type="button" class="icon-btn sm" aria-label="Regex mode">${ms('regular_expression')}</button><button type="button" class="icon-btn sm" aria-label="Regex builder">${ms('construction')}</button></div>`;
const stepper = (v, label) => `<div class="stepper" style="display: inline-flex; align-items: center; gap: 4px; border: 1px solid var(--outline); border-radius: 999px; padding: 2px"><button type="button" class="icon-btn sm" aria-label="Decrease ${label}">${ms('remove')}</button><b class="mono" style="min-width: 54px; text-align: center">${v}</b><button type="button" class="icon-btn sm" aria-label="Increase ${label}">${ms('add')}</button></div>`;
const ic = (icon, tone = '') => `<span class="ic${tone ? ' ' + tone : ''}">${ms(icon)}</span>`;
const card = (title, inner, { span = 6, icon, tone = '', cls = '', right = '' } = {}) => `<section class="card span-${span}${cls ? ' ' + cls : ''}"><div class="card-head">${icon ? ic(icon, tone) : ''}<h3>${title}</h3>${right}</div>${inner}</section>`;
const grid = (...xs) => `<div class="grid">${xs.join('')}</div>`;
const row = (...xs) => `<div class="row">${xs.join('')}</div>`;
const stack = (...xs) => `<div class="stack">${xs.join('')}</div>`;
const kpis = (items) => `<div class="kpis">${items.map(([v, l]) => `<div class="kpi"><b>${v}</b><span>${l}</span></div>`).join('')}</div>`;
const stats = (items) => `<div class="hero-stats">${items.map(([v, l, tone]) => `<div class="stat${tone ? ' ' + tone : ''}"><b>${v}</b><span>${l}</span></div>`).join('')}</div>`;
const table = (cols, rows) => `<div class="tbl-wrap"><table class="tbl"><thead><tr>${cols.map((c) => `<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const out = (text) => `<div class="out" style="white-space: pre-wrap">${text}</div>`;
const flag = (name, flagName, control, help) => `<div class="flag-card"><div class="row nowrap">${ibtn('info', 'About ' + name)}<b style="flex: 1">${name}</b><code class="small muted">${flagName}</code></div>${control}<div class="small muted">${help}</div></div>`;
const pick = (icon, title, sub, on) => `<button type="button" class="pick-row" role="radio" aria-checked="${on}"><span class="ava">${ms(icon)}</span><span class="meta"><b>${title}</b><span>${sub}</span></span><span class="radio-dot"></span></button>`;
// The website's home hero carries the real app: dark and light captures uploaded to the canvas.
const heroShot = () => `<div class="hero-shot">${['dark', 'light'].map((th) => `<img class="shot-${th}" src="${assetUrl(`assets/shot-${th}.webp`)}" alt="Material Tailscale editing tailscale set preferences with rich controls, captured from the built app" width="1120" height="760">`).join('')}</div>`;
const hero = (art, eyebrowIcon, eyebrow, en, yue, desc, actions = '', extra = '') => `<section class="hero-band${art === 'shot' ? ' has-shot' : ''}"><div class="hero-text"><span class="hero-eyebrow">${ms(eyebrowIcon)}${eyebrow}</span><h1>${en}${yue ? `<span class="yue">${yue}</span>` : ''}</h1><p>${desc}</p>${actions ? `<div class="hero-actions">${actions}</div>` : ''}${extra}</div>${art === 'shot' ? heroShot() : `<div class="hero-art">${ART[art]}</div>`}</section>`;
const tabArrow = (dir) => `<button type="button" class="icon-btn sm mtabs-arrow ${dir}" tabindex="-1" aria-label="${dir === 'prev' ? 'Show earlier sections' : 'Show more sections'}" title="${dir === 'prev' ? 'Show earlier sections' : 'Show more sections'}">${ms(dir === 'prev' ? 'chevron_left' : 'chevron_right')}</button>`;
const mtabs = (labels, sel, more = false) => `<div class="mtabs-wrap${more ? ' can-right' : ''}">${tabArrow('prev')}<div class="mtabs" role="tablist">${labels.map(([icon, l]) => `<button type="button" class="mtab" role="tab" aria-selected="${l === sel}">${ms(icon)}${l}</button>`).join('')}</div>${tabArrow('next')}</div>`;
const peer = (name, os, ip, path, tags, meta, exit) => `<article class="peer-card" tabindex="0"><div class="row nowrap"><span class="ava">${ms(os === 'Android' || os === 'iOS' ? 'smartphone' : os === 'tvOS' ? 'tv' : os === 'Linux' ? 'dns' : 'laptop')}</span><div style="flex: 1; min-width: 0"><div class="name">${name}</div><div class="ip">${ip}</div></div>${badge(path, path === 'direct' ? 'ok' : path === 'relay' ? 'warn' : 'info')}${ibtn('more_vert', 'More actions')}</div><div class="row">${tags.map((t) => chip(t)).join('')}${exit ? chip(ms('travel_explore') + 'exit node') : ''}${chip(os)}</div><div class="small muted">${meta}</div><div class="row">${btn('Ping', 'network_ping', 'small outline')}${btn('SSH', 'terminal', 'small outline')}${btn('Send', 'send', 'small outline')}</div></article>`;

